import { mkdir, readFile, rename, rm, writeFile } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import path from 'node:path';

/**
 * Where binary files live. The store only talks to this interface, so the local provider used for development and the
 * pilot can be replaced by an S3-compatible one without touching routes or the database (which keeps metadata only).
 * Keys are generated by the backend and are never exposed as paths to the browser.
 */
export interface ObjectStorage {
  put(key: string, data: Buffer, options: { contentType: string }): Promise<void>;
  /** Returns null when the object does not exist. */
  get(key: string): Promise<Buffer | null>;
  /** Idempotent: deleting a missing object is not an error. */
  delete(key: string): Promise<void>;
}

const keyPattern = /^[a-z0-9][a-z0-9/_.-]{0,199}$/;
export function assertSafeObjectKey(key: string) {
  if (!keyPattern.test(key) || key.includes('..') || key.includes('//') || key.endsWith('/')) throw new Error('Invalid object key.');
  return key;
}

/** Filesystem provider for development and the local pilot. Writes are atomic (temp file + rename). */
export class LocalObjectStorage implements ObjectStorage {
  private readonly root: string;
  constructor(rootDir: string) { this.root = path.resolve(rootDir); }
  private resolve(key: string) {
    const target = path.resolve(this.root, assertSafeObjectKey(key));
    if (target !== this.root && !target.startsWith(this.root + path.sep)) throw new Error('Invalid object key.');
    return target;
  }
  async put(key: string, data: Buffer, _options: { contentType: string }) {
    const target = this.resolve(key);
    await mkdir(path.dirname(target), { recursive: true });
    const temporary = `${target}.${randomUUID()}.tmp`;
    try { await writeFile(temporary, data, { flag: 'wx' }); await rename(temporary, target); }
    catch (error) { await rm(temporary, { force: true }).catch(() => undefined); throw error; }
  }
  async get(key: string) {
    try { return await readFile(this.resolve(key)); }
    catch (error) { if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null; throw error; }
  }
  async delete(key: string) { await rm(this.resolve(key), { force: true }); }
}

/** In-memory provider for tests. */
export class MemoryObjectStorage implements ObjectStorage {
  readonly objects = new Map<string, Buffer>();
  async put(key: string, data: Buffer) { this.objects.set(assertSafeObjectKey(key), Buffer.from(data)); }
  async get(key: string) { return this.objects.get(assertSafeObjectKey(key)) ?? null; }
  async delete(key: string) { this.objects.delete(assertSafeObjectKey(key)); }
}

export function defaultObjectStorage(): ObjectStorage {
  return new LocalObjectStorage(process.env.OBJECT_STORAGE_DIR ?? path.resolve(process.cwd(), '.local-object-storage'));
}
